["triggers"] = {
{
["trigger"] = {
["use_absorbMode"] = true,
["subeventPrefix"] = "SPELL",
["customIcon"] = "function()\n    return aura_env.fileId\nend",
["debuffType"] = "HELPFUL",
["type"] = "custom",
["use_absorbHealMode"] = true,
["custom_type"] = "status",
["unit"] = "player",
["event"] = "Unit Characteristics",
["customStacks"] = "function()\n    return aura_env.buffSize\nend",
["events"] = "PLAYER_ENTERING_WORLD,UNIT_AURA",
["spellIds"] = {
},
["custom"] = "function(event)\n    local spellId = 372470 --Scarlet Adaptation\n    local index = nil\n    \n    for i=1,40 do\n        if (not C_UnitAuras.GetBuffDataByIndex(\"player\", i)) then return false end\n        if C_UnitAuras.GetBuffDataByIndex(\"player\", i).spellId == spellId then\n            index = i\n            break\n        end\n    end\n    \n    if index then\n        local buffSize, stat = nil\n        local multiplier = 2.254 -- Max storage for this buff is Intellect * multiplier. This value was taken from 10.1.5 Build 50199\n        \n        aura_env.buffSize = C_UnitAuras.GetBuffDataByIndex('player', index).points[1]\n        stat = select(2, UnitStat(\"player\", 4)); --4 is Intellect\n        aura_env.fileId = C_UnitAuras.GetBuffDataByIndex('player', index).icon\n        if (aura_env.buffSize >= floor(stat * multiplier)) then \n            aura_env.forceGlow = true    \n        else aura_env.forceGlow = false\n        end\n        \n        return true\n    end\n    return false\nend",
["use_mainstat"] = false,
["check"] = "event",
["subeventSuffix"] = "_CAST_START",
