["custom_type"] = "event",
["custom"] = "function(event, unit, castGUID, spellID)\n    local function incrementWire()\n        local wire = aura_env.smls_wp\n        local mine = aura_env.smls_mp or 0\n        \n        if aura_env.config.smls_pt_debug then\n            print(\"[SMLS DEBUG] New wirecount:\", wire)\n        end\n        \n        local minePhases = {\n            [1] = true, [2] = true,\n            [4] = true, [5] = true,\n            [7] = true, [8] = true,\n        }\n        \n        if minePhases[wire] then\n            aura_env.smls_mp = aura_env.smls_mp + 1\n            if aura_env.config.smls_pt_debug then\n                print(\"[SMLS DEBUG] Mine phase INCREMENTED →\", _G.SMLS_minephase)\n            end\n        end\n        return true\n    end\n    \n    if unit and (unit == \"boss1\" or unit == \"boss2\") and spellID == 1218418 then\n        if aura_env.config.smls_pt_debug then\n            print(\"[SMLS DEBUG] UNIT_SPELLCAST_SUCCEEDED from:\", unit, \"spellId:\", spellID)        \n            print(\"[SMLS DEBUG] Wire Transfer detected via UNIT_SPELLCAST_SUCCEEDED! New wirecount:\", _G.SMLS_wirecount)\n        end\n        \n        return incrementWire()\n    end\n    \n    return false\nend",
