["default"] = false,
["width"] = 2,
},
},
["displayText"] = "%p",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["actions"] = {
["start"] = {
["do_custom"] = true,
["custom"] = "function mainDebug()\n    print(\"[SMLS DEBUGGER] Activated!\")\n    \n    -- Basic state\n    print(\"------------- SMLS STATE -------------\")\n    print(\"SMLS_minephase:\", _G.SMLS_minephase or \"nil\")\n    print(\"SMLS_wirecount:\", _G.SMLS_wirecount or \"nil\")\n    print(\"SMLS_note:\", _G.SMLS_note or \"nil\")\n    \n    -- Assignment table check\n    if _G.SMLS_Assignments then\n        print(\"SMLS_Assignments loaded:\", type(_G.SMLS_Assignments))\n        for marker, phases in pairs(_G.SMLS_Assignments) do\n            local summary = {}\n            for phase, index in pairs(phases) do\n                table.insert(summary, \"[\" .. tostring(phase) .. \"]=\" .. tostring(index))\n            end\n            print(\" -\", marker, \"=>\", table.concat(summary, \", \"))\n        end\n    else\n        print(\"SMLS_Assignments: nil ❌\")\n    end\n    \n    -- Get first 10 names from MRT note (sanitized)\n    if _G.SMLS_note then\n        print(\"------------- PARSED NOTE -------------\")\n        local i = 1\n        for word in string.gmatch(_G.SMLS_note, \"[^,%s]+\") do\n            local stripped = word:gsub(\"|c%x%x%x%x%x%x%x%x\", \"\"):gsub(\"|r\", \"\"):gsub(\"%-.*\", \"\")\n            print(\"[\" .. i .. \"]\", stripped)\n            i = i + 1\n            if i > 10 then break end\n        end\n    end\n    \n    -- Assigned player output per marker (using GetAssignedPlayer)\n    print(\"------------- ASSIGNMENTS -------------\")\n    if _G.SMLS_GetAssignedPlayer then\n        local markers = {\"Skull\", \"Circle\", \"Moon\", \"Star\", \"Cross\", \"Diamond\", \"Square\", \"Triangle\"}\n        for _, marker in ipairs(markers) do\n            local name = _G.SMLS_GetAssignedPlayer(marker)\n            print(marker .. \": \" .. (name or \"nil\"))\n        end\n    else\n        print(\"SMLS_GetAssignedPlayer missing ❌\")\n    end\n    \n    -- Check unit names for the first 5 raid members (to confirm presence of the player)\n    print(\"------------- RAID UNIT NAMES -------------\")\n    for i = 1, 5 do\n        local unitName = UnitName(\"raid\" .. i)\n        print(\"raid\" .. i, unitName or \"nil\")\n    end\n    \n    -- Backups: check raid and party units\n    print(\"------------- BACKUP RAID/PARTY NAMES -------------\")\n    for i = 6, 10 do\n        local unitName = UnitName(\"raid\" .. i) or UnitName(\"party\" .. i)\n        print(\"raid/party\" .. i, unitName or \"nil\")\n    end\n    \n    -- Helper function to print tables nicely\n    local function printTable(t, name)\n        if not t then\n            print(name .. \" is nil\")\n            return\n        end\n        \n        print(name .. \" = {\")\n        for i, v in ipairs(t) do\n            print(\"  [\" .. i .. \"] = \" .. tostring(v))\n        end\n        print(\"}\")\n    end    \n    print(\"------------- END DEBUG -------------\")\nend\n\nif aura_env.config.smls_debugger_debug then\n    mainDebug()\nend\n\n\n\n",
},
