["Lunar Effect - MRT Helper"] = {
["frameStrata"] = 1,
["wagoID"] = "wxmTS5FG8",
["authorOptions"] = {
{
["type"] = "description",
["text"] = "Debug Statements?",
["fontSize"] = "large",
["width"] = 2,
},
},
["preferToUpdate"] = false,
["parent"] = "Lunar Effect - MRT Hook",
["yOffset"] = 0,
["regionType"] = "empty",
["information"] = {
},
["anchorPoint"] = "CENTER",
["xOffset"] = 0,
["tocversion"] = 110100,
["url"] = "https://wago.io/wxmTS5FG8/1",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "-- Init our MRT Note helper global\n_G[\"LE_MRT_Note\"] = _G[\"LE_MRT_Note\"] or \"\"",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "event",
["custom_hide"] = "timed",
["duration"] = "0.1",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["spellIds"] = {
},
["events"] = "LE_MRT_HELPER",
["check"] = "event",
["custom"] = "function(event)\n    local function cleanName(raw, trunc)\n        local trimmed = raw:match(\"^%s*(.-)%s*$\") or \"\"\n        \n        -- Preserve {raidIcon} markers\n        if trimmed:match(\"^%b{}$\") then\n            return trimmed, trimmed  -- No cleaning or truncation\n        end\n        \n        local color = trimmed:match(\"|c%x%x%x%x%x%x%x%x\") or \"|cFFFFFFFF\"\n        local stripped = trimmed\n        :gsub(\"|c%x%x%x%x%x%x%x%x\", \"\")\n        :gsub(\"|r\", \"\")\n        :gsub(\"%-.*\", \"\")\n        :gsub(\"[|]\", \"\")\n        :gsub(\"%s+\", \"\")\n        \n        local truncLen = tonumber(trunc) or 7\n        \n        local cleaned = stripped:sub(1, 12)\n        local display = color .. stripped:sub(1, truncLen) .. \"|r\"\n        \n        if aura_env and aura_env.config and aura_env.config.smls_utils_debug then\n            print(\"DEBUG: cleanName returning cleaned =\", cleaned, \"display =\", display)\n        end\n        \n        return cleaned, display\n    end\n    \n    \n    local note = _G.VExRT and _G.VExRT.Note and _G.VExRT.Note.Text1\n    \n    if note then\n        function _G.leGetMRTNote(startMarker, endMarker, trunc)\n            -- Validate startMarker\n            if type(startMarker) ~= \"string\" or startMarker == \"\" then\n                print(\"[MRT Helper] Error: startMarker is nil or not a string\")\n                return false\n            end\n            \n            -- Validate endMarker\n            if type(endMarker) ~= \"string\" or endMarker == \"\" then\n                print(\"[MRT Helper] Error: endMarker is nil or not a string\")\n                return false\n            end\n            \n            -- Validate trunc\n            if type(trunc) ~= \"number\" or math.floor(trunc) ~= trunc then\n                print(\"[MRT Helper] Error: trunc must be an integer\")\n                return false\n            end\n            \n            if trunc < 1 or trunc > 12 then\n                print(\"[MRT Helper] Error: trunc must be between 1 and 12\")\n                return false\n            end\n            \n            -- print(\"Start: \" .. startMarker .. \" End: \" .. endMarker .. \" Trunc: \" .. trunc)\n            \n            local mrtBody = note:match(startMarker .. \"%s*([%s%S]-)%s*\" .. endMarker)\n            \n            -- Parse names\n            local cleanedNames, rawNames = {}, {}\n            for word in string.gmatch(mrtBody, \"[^,%s]+\") do\n                local cleaned, display = cleanName(word)\n                table.insert(cleanedNames, cleaned)\n                table.insert(rawNames, display)\n            end\n            \n            return cleanedNames, rawNames\n        end\n    end\n    \nend",
["names"] = {
},
["debuffType"] = "HELPFUL",
},
["untrigger"] = {
},
},
["activeTriggerMode"] = -10,
},
["animation"] = {
["start"] = {
["type"] = "none",
["easeStrength"] = 3,
["duration_type"] = "seconds",
