["custom"] = "function(event, prefix, msg, channel, sender)\n    \n    if aura_env.config.smls_devtool_debug then\n        print(\"[SMLS DEBUG] ========== DevTools WeakAura Trigger ==========\")\n        print(\"[SMLS DEBUG] Event received:\", event)\n        print(\"[SMLS DEBUG] Prefix:\", tostring(prefix))\n        print(\"[SMLS DEBUG] Message:\", tostring(msg))\n        print(\"[SMLS DEBUG] Channel:\", tostring(channel))\n        print(\"[SMLS DEBUG] Sender:\", tostring(sender))\n    end\n    \n    if prefix ~= \"SMLSDEV\" then\n        if aura_env.config.smls_devtool_debug then\n            print(\"[SMLS DEBUG] Prefix is not SMLSDEV, ignoring.\")\n        end\n        return false\n    end\n    \n    if msg == \"wire\" then\n        if aura_env.config.smls_devtool_debug then\n            print(\"[SMLS DEBUG] Recognized message: wire\")\n            print(\"[SMLS DEBUG] Firing SMLSDEV_WIRE via addon message (SMLSDEV_EVENT, wire)\")\n        end\n        --C_ChatInfo.SendAddonMessage(\"SMLSDEV_EVENT\", \"wire\", \"RAID\")\n        return true\n        \n    elseif msg == \"reset\" then\n        if aura_env.config.smls_devtool_debug then\n            print(\"[SMLS DEBUG] Recognized message: reset\")\n            print(\"[SMLS DEBUG] Firing SMLSDEV_RESET via addon message (SMLSDEV_EVENT, reset)\")\n        end\n        C_ChatInfo.SendAddonMessage(\"SMLSDEV_EVENT\", \"reset\", \"RAID\")\n        return true\n    end\n    \n    if aura_env.config.smls_devtool_debug then\n        print(\"[SMLS DEBUG] Unrecognized message. No action taken.\")\n    end    \n    return false\nend",
