["custom"] = "function(allstates, event)\n    if event == \"OPTIONS\" then\n        local playerName = UnitName(\"player\")\n        \n        for i = 1, 10 do\n            local stacks = math.random(10)\n            \n            local _, randomClass = GetClassInfo(math.random(13))\n            local colorStr = RAID_CLASS_COLORS[randomClass].colorStr\n            local coloredName = string.format(\"|c%s%s|r\", colorStr, playerName)\n            \n            local duration = 10 + math.random(20)\n            \n            allstates[i] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 30,\n                expirationTime = GetTime() + duration,\n                stacks = stacks,\n                index = stacks,\n                name = coloredName,\n                autoHide = true\n            }\n        end\n    elseif event == \"STATUS\" then\n        if AuraUpdater then AuraUpdater:UpdateAnchorSettings(\"Lists\") end\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 0.1,\n            expirationTime = GetTime() + 0.1,\n            autoHide = true\n        }\n        \n        return true\n    end\nend",
