["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        for i = 1, 20 do\n            local affected = math.random(2) == 1\n            \n            local role = i <= 2 and \"TANK\" or i <= 6 and \"HEALER\" or \"DAMAGER\"\n            \n            if affected then\n                allstates[i] = {\n                    show = true,\n                    changed = true,\n                    progressType = \"timed\",\n                    duration = 45,\n                    expirationTime = GetTime() + 20 + math.random(25),\n                    unit = \"player\",\n                    roleIcon = aura_env.roleIcons[role],\n                    role = role,\n                    stacks = math.random(4, 20),\n                    matchCount = 1,\n                    autoHide = false\n                }\n            else\n                allstates[i] = {\n                    show = true,\n                    changed = true,\n                    unit = \"player\",\n                    roleIcon = aura_env.roleIcons[role],\n                    role = role,\n                    stacks = affected and math.random(4, 20) or 0,\n                    matchCount = 0,\n                    autoHide = false\n                }\n            end\n            \n        end\n    end\nend",
