["stasis duration bar"] = {
["sparkWidth"] = 10,
["iconSource"] = -1,
["wagoID"] = "SU5f2N1fO",
["authorOptions"] = {
},
["preferToUpdate"] = false,
["customText"] = "function()\n    local empowerLevel = aura_env.state.empowerLevel\n    local empowerLevelText = nil\n    if (empowerLevel == 1) then\n        empowerLevelText = \"I\"\n    end\n    if (empowerLevel == 2) then\n        empowerLevelText = \"II\"\n    end\n    if (empowerLevel == 3) then\n        empowerLevelText = \"III\"\n    end\n    if (empowerLevel == 4) then\n        empowerLevelText = \"IV\"\n    end\n    \n    return empowerLevelText, aura_env.state.targetName\nend",
["yOffset"] = 105,
["anchorPoint"] = "CENTER",
["config"] = {
},
["sparkOffsetX"] = 0,
["sparkRotation"] = 0,
["sparkRotationMode"] = "AUTO",
["url"] = "https://wago.io/SU5f2N1fO/8",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["custom"] = "aura_env.spellIds = {\n    [366155] = true, -- Reversion\n    [364343] = true, -- Echo\n    [360995] = true, -- Verdant Embrace\n    [355913] = true, -- Emerald Blossom\n    [355936] = true, -- Dream Breath\n    [382614] = true, -- Dream Breath (Font of Magic)\n    [367226] = true, -- Spiritbloom\n    [382731] = true, -- Spiritbloom (Font of Magic)\n    [360823] = true, -- Naturalize\n    [374251] = true, -- Cauterizing Flame\n    [373861] = true, -- Temporal Anomaly\n    [361469] = true, -- Living Flame\n    [431443] = true, -- Chrono Flames\n    [443328] = true, -- Engulf\n}\n\naura_env.empoweredHealIds = {\n    [355941] = true, -- Dream Breath\n    [367230] = true, -- Spiritbloom\n}\n\naura_env.tipTheScalesId = 370553\naura_env.stasisId = 370537\naura_env.stasisDoneId = 370562\n\naura_env.spellIndex = 1\naura_env.tipTheScales = false\naura_env.tipTheScalesRemoveTime = 0\naura_env.lastHealCastTime = 0\naura_env.lastEmpowerSpellID = 0\n\naura_env.getSpellTarget = function(destGUID, destName)\n    if (destGUID == \"\" or not aura_env.config[\"show_target\"]) then\n        return \"\"\n    else\n        local _, englishClass = GetPlayerInfoByGUID(destGUID)\n        local _, _, _, argbHex = GetClassColor(englishClass)\n        return WrapTextInColorCode(string.sub(destName, 1, aura_env.config[\"target_name_limit\"]), argbHex)\n    end\nend\n\naura_env.addSpell = function(allStates, spellId, empowerLevel, destGUID, destName)\n    local state = allStates[aura_env.spellIndex]\n    if (not state) then\n        return\n    end\n    local spellInfo = C_Spell.GetSpellInfo(spellId)\n    state.icon = spellInfo.iconID\n    state.changed = true\n    state.spellId = spellId\n    state.spellTarget = aura_env.getSpellTarget(destGUID, destName)\n    state.empowerLevel = empowerLevel\n    \n    aura_env.spellIndex = aura_env.spellIndex + 1\nend\n\naura_env.getMaxEmpowerLevel = function()\n    return IsPlayerSpell(375783) and 4 or 3\nend",
},
