["Reel Assistant kill order"] = {
["outline"] = "OUTLINE",
["wagoID"] = "Jvpud9Ahy",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://wago.io/LiquidUndermine/4",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "local sortedTokenOrder = {\n    FS = \"FS\", -- Reward: Shock and Flame\n    SF = \"FS\", -- Reward: Shock and Flame\n    \n    BS = \"BS\", -- Reward: Shock and Bomb\n    SB = \"BS\", -- Reward: Shock and Bomb\n    \n    BF = \"BF\", -- Reward: Flame and Bomb\n    FB = \"BF\", -- Reward: Flame and Bomb\n    \n    CF = \"CF\", -- Reward: Flame and Coin\n    FC = \"CF\", -- Reward: Flame and Coin\n    \n    CS = \"CS\", -- Reward: Coin and Shock\n    SC = \"CS\", -- Reward: Coin and Shock\n    \n    BC = \"BC\", -- Reward: Coin and Bomb\n    CB = \"BC\", -- Reward: Coin and Bomb\n}\n\nlocal combinationToText = {\n    FS = \"|cFF226FFFShock|r & |cFFFF6B29Flame|r\",\n    BS = \"|cFF226FFFShock|r & |cFF7B8585Bomb|r\",\n    BF = \"|cFFFF6B29Flame|r & |cFF7B8585Bomb|r\",\n    CF = \"|cFFFF6B29Flame|r & |cFFFFD429Coin|r\",\n    CS = \"|cFFFFD429Coin|r & |cFF226FFFShock|r\",\n    BC = \"|cFFFFD429Coin|r & |cFF7B8585Bomb|r\",\n}\n\n-- Returns a list of token priorities, structued as <[token combination] = priority>\n-- Uses MRT note if supplied. Otherwise uses the default priority list.\nfunction aura_env.GetTokenOrder()\n    local tokenPriorities = {}\n    local order = {}\n    \n    for _, line in LiquidWeakAuras:IterateNoteAssignment() do\n        line = line:upper()\n        \n        for tokenCombination in string.gmatch(line, \"%S+\") do\n            tokenCombination = sortedTokenOrder[tokenCombination]\n            \n            -- Check if this is a valid token combination (correct letters, in either order)\n            -- And whether this is the first time it's been listed (ignore subsequent times)\n            local validTokenCombination = tokenCombination and not tContains(tokenPriorities, tokenCombination)\n            \n            if validTokenCombination then\n                table.insert(tokenPriorities, tokenCombination)\n            end\n        end\n    end\n    \n    if not next(tokenPriorities) then\n        tokenPriorities = {\n            \"CF\", \"CS\", \"FS\", \"BF\", \"BS\", \"BC\"\n        }\n    end\n    \n    for _, tokenCombination in ipairs(tokenPriorities) do\n        local text = combinationToText[tokenCombination]\n        \n        table.insert(order, text)\n    end\n    \n    return order\nend",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["custom_hide"] = "timed",
["spellIds"] = {
},
["events"] = "UNIT_SPELLCAST_START:boss, ENCOUNTER_START",
["subeventPrefix"] = "SPELL",
["names"] = {
},
["custom_type"] = "stateupdate",
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        local assignments = {\n            \"|cFF226FFFShock|r & |cFFFF6B29Flame|r\",\n            \"|cFF226FFFShock|r & |cFF7B8585Bomb|r\",\n            \"|cFFFF6B29Flame|r & |cFF7B8585Bomb|r\",\n            \"|cFFFF6B29Flame|r & |cFFFFD429Coin|r\",\n            \"|cFFFFD429Coin|r & |cFF226FFFShock|r\",\n            \"|cFFFFD429Coin|r & |cFF7B8585Bomb|r\",\n        }\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 4,\n            expirationTime = GetTime() + 4,\n            assignment = assignments[math.random(#assignments)],\n            autoHide = true\n        }\n    elseif event == \"UNIT_SPELLCAST_START\" then\n        local _, castGUID, spellID = ...\n        \n        if not castGUID then return end\n        \n        if spellID == 461060 then -- Spin To Win!\n            aura_env.count = aura_env.count + 1\n            \n            local assignment = aura_env.order[aura_env.count]\n            \n            if assignment then\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    progressType = \"timed\",\n                    duration = 4,\n                    expirationTime = GetTime() + 4,\n                    assignment = assignment,\n                    autoHide = true\n                }\n                \n                return true\n            end\n        end\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.count = 0\n        aura_env.order = aura_env.GetTokenOrder()\n    end\nend\n\n\n\n",
