["parent"] = "[PRESERVATION] 5 ESSENCE",
["adjustedMax"] = "",
["adjustedMin"] = "",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["spark"] = false,
["sparkRotation"] = 0,
["sparkRotationMode"] = "AUTO",
["url"] = "quazii.com",
["backgroundColor"] = {
0.12156863510609,
0.12156863510609,
