["check"] = "event",
["spellIds"] = {
},
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 5,\n            expirationTime = GetTime() + 5,\n            autoHide = true\n        }\n    elseif event == \"LIQUID_CUSTOM_EVENT\" then\n        local id, encounterStart = ...\n        \n        if id ~= aura_env.id then return end\n        if encounterStart ~= aura_env.encounterStart then return end\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 5,\n            expirationTime = GetTime() + 5,\n            autoHide = true\n        }\n        \n        C_Timer.After(12, function() WeakAuras.ScanEvents(\"LIQUID_CUSTOM_EVENT\", aura_env.id, aura_env.encounterStart) end)\n        \n        return true\n    elseif event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        local _, castGUID, spellID = ...\n        \n        if not castGUID then return end\n        \n        if spellID == 465322 then -- Hot Hot Heat\n            WeakAuras.ScanEvents(\"LIQUID_CUSTOM_EVENT\", aura_env.id, aura_env.encounterStart)\n        end\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.encounterStart = GetTime()\n    end\nend",
