["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() then return end\n    \n    if not aura_env.last or aura_env.last < GetTime() - 1 then\n        aura_env.last = GetTime()\n        \n        SendChatMessage(\"Can't soak\")\n    end\nend",
