["SW_SMLS - Assignment P1"] = {
["parent"] = "SW_SMLS Player Markers",
["customText"] = "function()\n    local p = aura_env.swma_p1 or \"|c00C41E3ANONE|r\"\n    \n    local playerName = UnitName(\"player\") or \"Unknown\"\n    playerName = playerName:sub(1, 7) -- truncate to 7 characters\n    \n    -- Strip color for comparison\n    local _, clean_p = p:match(\"|c%x%x%x%x%x%x%x%x([^|]+)|r\")\n    if clean_p and clean_p == playerName then\n        -- If it matches, add |c0000FF98>|r and |c0000FF98<|r around\n        local highlightOpen = \"|c0000FF98>|r\"\n        local highlightClose = \"|c0000FF98<|r\"\n        return highlightOpen .. p .. highlightClose\n    end\n    \n    return p\nend",
