["custom"] = "if AuraUpdater then AuraUpdater:UpdateAnchorSettings(\"CoTankIcons\") end\n\naura_env.tankClasses = {\n    [1] = \"WARRIOR\",\n    [2] = \"PALADIN\",\n    [3] = \"DEATHKNIGHT\",\n    [4] = \"DRUID\",\n    [5] = \"MONK\",\n    [6] = \"DEMONHUNTER\"\n}",
