["custom"] = "function(allstates, event)\n    if event == \"OPTIONS\" then\n        local randomTankClass = aura_env.tankClasses[math.random(#aura_env.tankClasses)]\n        local colorStr = RAID_CLASS_COLORS[randomTankClass].colorStr\n        local coloredName = string.format(\"|c%sCo-tank|r\", colorStr)\n        \n        allstates[1] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 20,\n            expirationTime = GetTime() + 10 + math.random(10),\n            stacks = math.random(4),\n            name = coloredName,\n            icon = 132363,\n            autoHide = true\n        }\n        \n        allstates[2] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 20,\n            expirationTime = GetTime() + 10 + math.random(10),\n            stacks = math.random(4),\n            icon = 464973,\n            name = coloredName,\n            autoHide = true\n        }\n    elseif event == \"STATUS\" then\n        if AuraUpdater then AuraUpdater:UpdateAnchorSettings(\"CoTankIcons\") end\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 0.1,\n            expirationTime = GetTime() + 0.1,\n            autoHide = true\n        }\n        \n        return true\n    end\nend",
