["DEVASTATION 5 ESSENCE"] = {
["sparkWidth"] = 10,
["sparkOffsetX"] = 0,
["wagoID"] = "ZJ_Lytik1",
["xOffset"] = 0,
["adjustedMax"] = "",
["adjustedMin"] = "",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["semver"] = "10.0.46",
["sparkRotation"] = 0,
["sparkRotationMode"] = "AUTO",
["url"] = "quazii.com",
["actions"] = {
["start"] = {
