["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 6,\n            expirationTime = GetTime() + 6,\n            additionalProgress = {\n                {\n                    min = 0,\n                    max = 2.5\n                }\n            },\n            autoHide = true\n        }\n    elseif event == \"TRIGGER\" then\n        local _, triggerStates = ...\n        local triggerState = triggerStates[\"\"]\n        \n        if not (triggerState and triggerState.show) then\n            local state = allstates[\"\"]\n            \n            if state then\n                state.show = false\n                state.changed = true\n                \n                return true\n            end\n        end\n        \n        allstates[\"\"] = {\n            show = triggerState.show,\n            changed = true,\n            progressType = triggerState.progressType,\n            duration = triggerState.duration,\n            expirationTime = triggerState.expirationTime,\n            additionalProgress = {\n                {\n                    min = 0,\n                    max = 2.5\n                }\n            },\n            autoHide = true\n        }\n        \n        return true\n    end\nend",
