},
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        aura_env.ShowLightning(1)\n    elseif event == \"LIQUID_FOOT_BLASTER_ASSIGNMENT\" then\n        local set, assignments, isMythic = ...\n        \n        if next(assignments) then\n            aura_env.ShowLightning(set, isMythic)\n            \n            allstates[\"\"] = {\n                show = true,\n                changed = true\n            }\n        else\n            local state = allstates[\"\"]\n            \n            if state then\n                state.show = false\n                state.changed = true\n            end\n        end\n        \n        return true\n    end\nend",
