["anchorFrameType"] = "SCREEN",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "aura_env.last = GetTime()\n\nlocal points = {\n    { -- Dungeon One\n        atlas = \"Vehicle-HammerGold-1\",\n        label = \"\",\n        [2266] = {\n            alpha = 1,\n            x = 0.6464,\n            y = 0.4409,\n        },\n    },\n    { -- Dungeon Two\n        atlas = \"AlliedRace-Crest-Mechagnome\",\n        label = \"Mechagon\",\n        [2266] = {\n            alpha = 1,\n            x = 0.7435,\n            y = 0.4726,\n        },\n    },\n    { -- Dungeon Three\n        atlas = \"Mobile-MechanicIcon-Lethal\",\n        label = \"Theatre of Pain\",\n        [2266] = {\n            alpha = 1,\n            x = 0.7729,\n            y = 0.6171,\n        },\n    },\n    { -- Dungeon Four\n        atlas = \"AlliedRace-Crest-Zandalari\",\n        label = \"MOTHERLODE\",\n        [2266] = {\n            alpha = 1,\n            x = 0.7037,\n            y = 0.7267,\n        },\n    },\n    { -- Dungeon Five\n        atlas = \"Vehicle-HammerGold-1\",\n        label = \"\",\n        [2266] = {\n            alpha = 1,\n            x = 0.6059,\n            y = 0.6927,\n        },\n    },\n    { -- Dornogal\n        atlas = \"WarlockPortalAlliance\",\n        label = \"Dornogal\",\n        [2266] = {\n            alpha = 1,\n            x = 0.4348,\n            y = 0.4991,\n        },\n    },\n}\n\nif not aura_env.region.map then\n    local map = CreateFrame(\"FRAME\",nil,aura_env.region)\n    map:SetPoint(\"CENTER\",aura_env.region)\n    \n    for i=1,#points do\n        map[i] = CreateFrame(\"FRAME\",nil,map)\n        map[i]:SetPoint(\"TOPLEFT\")\n        map[i]:SetSize(32,32)\n        map[i].label = map[i]:CreateFontString(nil,\"ARTWORK\",\"GameFontHighlight\")\n        map[i].label:SetPoint(\"BOTTOM\",map[i],\"TOP\")\n        map[i].label:SetFont(\"Fonts\\\\FRIZQT__.TTF\",12,\"OUTLINE\")\n        map[i].label:SetShadowOffset(0,0)\n        map[i].label:SetText(points[i].label)\n        map[i].icon = map[i]:CreateTexture(nil,\"ARTWORK\")\n        map[i].icon:SetAllPoints(map[i])\n        map[i].icon:SetAtlas(points[i].atlas)\n    end\n    \n    map.player = CreateFrame(\"FRAME\",nil,map)\n    map.player:SetPoint(\"CENTER\",map)\n    map.player:SetFrameLevel(20)\n    \n    map.player.icon = map.player:CreateTexture(nil,\"ARTWORK\")\n    map.player.icon:SetAllPoints(map.player)\n    map.player.icon:SetAtlas(\"\")\n    \n    aura_env.region.map = map\nend\n\nlocal config = aura_env.config\nlocal hud = config.hud/100\nlocal alpha = config.alpha/100\nlocal scale = config.scale/100\nlocal text = config.text\nlocal icons = \"|A:mageportalhorde:24:24|a Portals\"\n\nif aura_env.region.map then\n    local map = aura_env.region.map\n    map.player:SetSize(32*scale,32*scale)\n    map.player:SetAlpha(alpha)\n    for i=1,#points do\n        map[i]:SetSize(32*scale,32*scale)\n        map[i].label:SetFont(\"Fonts\\\\FRIZQT__.TTF\",text,\"OUTLINE\")\n    end\nend\n\nlocal GetMapWorldSize = C_Map.GetMapWorldSize\nlocal GetBestMapForUnit = C_Map.GetBestMapForUnit\nlocal GetPlayerMapPosition = C_Map.GetPlayerMapPosition\nlocal GetPlayerFacing = GetPlayerFacing\nlocal GetCoordinates = function()\n    local map = GetBestMapForUnit(\"player\")\n    if not map then return end\n    local pos = GetPlayerMapPosition(map,\"player\")\n    if not pos then return end\n    return map,pos.x,pos.y\nend\n\naura_env.update = function()\n    local map = aura_env.region.map\n    if not map then return end\n    \n    local angle = GetPlayerFacing()\n    local mapID, playerX, playerY = GetCoordinates()\n    if not angle or not mapID or not playerX or not playerY then return end\n    \n    local width, height = GetMapWorldSize(mapID)\n    if not width or not height then return end\n    \n    local cosAngle, sinAngle = math.cos(angle), math.sin(angle)\n    local proportion = height / width\n    \n    -- Adjust width for HUD scaling\n    width = width * 2 * hud\n    map:SetSize(width, width)\n    \n    -- 45-degree tilt components\n    local tiltX, tiltY = math.cos(math.rad(355)), math.sin(math.rad(155))\n    \n    -- Set a fixed FOV value (more extreme correction)\n    local fov = 45\n    \n    for i = 1, #points do\n        if not map[i] then break end\n        if not points[i][mapID] then mapID = 2266 end\n        \n        local distanceX = (points[i][mapID].x - playerX)\n        local distanceY = (points[i][mapID].y - playerY) * proportion\n        \n        -- Apply player-facing rotation\n        local pointX = cosAngle * distanceX - sinAngle * distanceY\n        local pointY = sinAngle * distanceX + cosAngle * distanceY\n        \n        -- Apply 45-degree tilt by adjusting both X and Y with more extreme FOV correction\n        local tiltedX = pointX * tiltX * (90 / fov)\n        local tiltedY = pointY * tiltY * (90 / fov)\n        \n        map[i]:SetAlpha(points[i][mapID].alpha * alpha)\n        map[i]:SetShown(true)\n        map[i]:ClearAllPoints()\n        \n        -- Update position with tilt and FOV applied\n        map[i]:SetPoint(\"CENTER\", map, \"CENTER\", tiltedX * width, (tiltedY * width) * -1)\n    end\nend\n\n\n",
["do_custom"] = true,
},
