},
["spellIds"] = {
},
["custom"] = "function(allstates, event, wire, isMythic)\n    if event == \"SW_SMLS_FB\" then\n        if wire == 0 then\n            -- Hide all lightning manually\n            for texName, texture in pairs(aura_env.region.mapTextures) do\n                if texName:find(\"Lightning\") then\n                    texture:SetShown(false)\n                end\n            end\n        else\n            aura_env.ShowLightning(wire, isMythic)\n        end\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true\n        }\n        return true\n    end\nend",
["events"] = "SW_SMLS_FB",
["subeventPrefix"] = "SPELL",
["check"] = "event",
