["events"] = "ENCOUNTER_START,ENCOUNTER_END",
["custom_type"] = "event",
["custom"] = "function()\n    aura_env.smls_wp = 0\n    aura_env.smls_mp = 0\n    \n    -- Force display of Wire Phase 1 Lightning\n    WeakAuras.ScanEvents(\"SW_SMLS_FB\", 1, aura_env.isMythic)\n    \n    return true\nend",
["duration"] = "0.5",
["debuffType"] = "HELPFUL",
["unit"] = "player",
