},
{
["trigger"] = {
["debuffType"] = "HELPFUL",
["type"] = "custom",
["events"] = "UNIT_SPELLCAST_SUCCEEDED",
["custom_type"] = "event",
["custom"] = "function(event, unit, castGUID, spellID)\n    if unit and (unit == \"boss1\" or unit == \"boss2\") and spellID == 1218418 then\n        -- Increment wire\n        aura_env.smls_wp = (aura_env.smls_wp or 0) + 1\n        local wire = aura_env.smls_wp\n        \n        -- Debug\n        if aura_env.config.smls_pt_debug then\n            print(\"[SMLS DEBUG] UNIT_SPELLCAST_SUCCEEDED from:\", unit, \"spellId:\", spellID)\n            print(\"[SMLS DEBUG] Wire Transfer detected! New wirecount:\", wire)\n        end\n        \n        C_Timer.After(12, function()\n                if WeakAuras.IsOptionsOpen() then return end -- don't overwrite while editing\n                WeakAuras.ScanEvents(\"SW_SMLS_UPDATEASSIGNMENTS\")\n        end)        \n        \n        -- Increment mine phase if needed\n        local minePhases = {\n            [1] = true, [2] = true,\n            [4] = true, [5] = true,\n            [7] = true, [8] = true,\n        }\n        \n        if minePhases[wire] then\n            aura_env.smls_mp = (aura_env.smls_mp or 0) + 1\n            if aura_env.config.smls_pt_debug then\n                print(\"[SMLS DEBUG] Mine phase INCREMENTED →\", aura_env.smls_mp)\n            end\n        end\n        \n        -- Special case Wire 8 (delayed mine phase 6)\n        if wire == 8 then\n            if aura_env.config.smls_pt_debug then\n                print(\"[SMLS DEBUG] Wire 8 detected! Starting delayed Mine Phase 6 after 20s.\")\n            end\n            \n            C_Timer.After(20, function()\n                    aura_env.smls_mp = (aura_env.smls_mp or 0) + 1\n                    aura_env.ShowLightning(0, aura_env.isMythic)\n                    \n                    if aura_env.config.smls_pt_debug then\n                        print(\"[SMLS DEBUG] Mine Phase 6 forced! Lightning hidden.\")\n                    end\n            end)\n        end\n        \n        -- Fire lightning update\n        WeakAuras.ScanEvents(\"SW_SMLS_FB\", wire, aura_env.isMythic)\n        \n        return true\n    end\n    \n    return false\nend",
