["custom"] = "function(event, prefix, msg, channel, sender)\n    -- Debugging optional\n    -- if aura_env.config and aura_env.config.smls_debug then\n    --     print(\"[SW_SMLS] Received:\", prefix, msg)\n    -- end\n    \n    if event ~= \"CHAT_MSG_ADDON\" then\n        return false\n    end\n    \n    if prefix == \"EXRTADD\" and msg:find(\"^multiline\") then\n        local noteText = nil\n        \n        if prefix == \"EXRTADD\" then\n            noteText = _G.VExRT and _G.VExRT.Note and _G.VExRT.Note.Text1\n        end\n        \n        if noteText then\n            aura_env.ProcessMRTNote(noteText)\n            return true -- optional depending if you want trigger animation, usually safe to return true\n        end\n    end\n    \n    return false\nend",
