["events"] = "SW_SMLS_UPDATEASSIGNMENTS",
["custom_type"] = "event",
["custom"] = "function(event)\n    if event ~= \"SW_SMLS_UPDATEASSIGNMENTS\" then\n        return false\n    end\n    \n    local function HasUnstableShrapnel(unit)\n        if not unit then return false end\n        local i = 1\n        while true do\n            local name, _, _, _, _, _, _, _, _, spellId = UnitDebuff(unit, i)\n            if not name then break end\n            if spellId == 1218342 then -- Unstable Shrapnel debuff ID\n                return true\n            end\n            i = i + 1\n        end\n        return false\n    end\n    \n    local function FindUnitByName(name)\n        for i = 1, 40 do\n            local unit = \"raid\"..i\n            if UnitExists(unit) then\n                if Ambiguate(UnitName(unit), \"short\") == name then\n                    return unit\n                end\n            end\n        end\n        return nil\n    end\n    \n    local function GetNextBackupReplacement()\n        if not aura_env.backupPlayers or #aura_env.backupPlayers == 0 then\n            return \"|c00C41E3ANONE|r\"\n        end\n        while #aura_env.backupPlayers > 0 do\n            local name = table.remove(aura_env.backupPlayers, 1)\n            local baseName = Ambiguate(name, \"short\")\n            local unit = FindUnitByName(baseName)\n            if unit and not UnitIsDeadOrGhost(unit) and not HasUnstableShrapnel(unit) then\n                return name\n            end\n        end\n        return \"|c00C41E3ANONE|r\"\n    end\n    \n    -- Make sure assignmentTable exists\n    if not aura_env.assignmentTable then\n        return false\n    end\n    \n    -- Make sure backupPlayers exists\n    if not aura_env.backupPlayers then\n        aura_env.backupPlayers = {}\n    end\n    \n    -- Copy the base assignments\n    local assignedPlayers = {}\n    \n    for i = 1, 8 do\n        assignedPlayers[i] = aura_env.assignmentTable[i]\n    end\n    \n    -- Validate players: dead, shrapnel, etc\n    for i = 1, 8 do\n        local name = assignedPlayers[i]\n        if name then\n            local baseName = Ambiguate(name, \"short\")\n            local unit = FindUnitByName(baseName)\n            if not unit or UnitIsDeadOrGhost(unit) or HasUnstableShrapnel(unit) then\n                assignedPlayers[i] = GetNextBackupReplacement()\n            end\n        end\n    end\n    \n    -- Push updated assignments\n    aura_env.swma_p1 = assignedPlayers[1] or \"|c00C41E3ANONE|r\"\n    aura_env.swma_p2 = assignedPlayers[2] or \"|c00C41E3ANONE|r\"\n    aura_env.swma_p3 = assignedPlayers[3] or \"|c00C41E3ANONE|r\"\n    aura_env.swma_p4 = assignedPlayers[4] or \"|c00C41E3ANONE|r\"\n    aura_env.swma_p5 = assignedPlayers[5] or \"|c00C41E3ANONE|r\"\n    aura_env.swma_p6 = assignedPlayers[6] or \"|c00C41E3ANONE|r\"\n    aura_env.swma_p7 = assignedPlayers[7] or \"|c00C41E3ANONE|r\"\n    aura_env.swma_p8 = assignedPlayers[8] or \"|c00C41E3ANONE|r\"\n    \n    -- Build new payload and send it out\n    local payload = table.concat({\n            aura_env.swma_p1,\n            aura_env.swma_p2,\n            aura_env.swma_p3,\n            aura_env.swma_p4,\n            aura_env.swma_p5,\n            aura_env.swma_p6,\n            aura_env.swma_p7,\n            aura_env.swma_p8,\n    }, \":\")\n    \n    -- Send the updated assignments to RAID\n    C_ChatInfo.SendAddonMessage(\"SW_SMLS_PA\", payload, \"RAID\")\n    \n    -- Fire local event to refresh text icons immediately\n    WeakAuras.ScanEvents(\"SW_SMLS_PA\")\n    \n    return true\nend",
