["do_custom"] = true,
["custom"] = "-- Register our prefix (make sure all players use the same one)\nC_ChatInfo.RegisterAddonMessagePrefix(\"LE_TIER_MAIN\")\n\n-- Table to hold the entire tier list\naura_env.tierList = nil\n\n-- Replace with actual Tier Item IDs off WoWHead.\naura_env.tierItemIDs = {\n    -- DK\n    [229253] = true, -- Helm\n    [229251] = true, -- Shoulder\n    [229256] = true, -- Chest\n    [229254] = true, -- Gloves\n    [229252] = true, -- Legs\n    \n    -- DH\n    [229316] = true, -- Helm\n    [229314] = true, -- Shoulder\n    [229319] = true, -- Chest\n    [229317] = true, -- Gloves\n    [229315] = true, -- Legs\n    \n    -- Druid\n    [229307] = true, -- Helm\n    [229305] = true, -- Shoulder\n    [229310] = true, -- Chest\n    [229308] = true, -- Gloves\n    [229306] = true, -- Legs\n    \n    -- Evoker\n    [229280] = true, -- Helm\n    [229278] = true, -- Shoulder\n    [229283] = true, -- Chest\n    [229281] = true, -- Gloves\n    [229279] = true, -- Legs\n    \n    -- Hunter\n    [229271] = true, -- Helm\n    [229269] = true, -- Shoulder\n    [229274] = true, -- Chest\n    [229272] = true, -- Gloves\n    [229270] = true, -- Legs\n    \n    -- Mage\n    [229343] = true, -- Helm\n    [229341] = true, -- Shoulder\n    [229346] = true, -- Chest\n    [229344] = true, -- Gloves\n    [229342] = true, -- Legs\n    \n    -- Monk\n    [229298] = true, -- Helm\n    [229296] = true, -- Shoulder\n    [229301] = true, -- Chest\n    [229299] = true, -- Gloves\n    [229297] = true, -- Legs\n    \n    -- Paladin\n    [229244] = true, -- Helm\n    [229242] = true, -- Shoulder\n    [229247] = true, -- Chest\n    [229245] = true, -- Gloves\n    [229243] = true, -- Legs\n    \n    -- Priest\n    [229334] = true, -- Helm\n    [229332] = true, -- Shoulder\n    [229337] = true, -- Chest\n    [229335] = true, -- Gloves\n    [229333] = true, -- Legs\n    \n    -- Rogue\n    [229289] = true, -- Helm\n    [229287] = true, -- Shoulder\n    [229292] = true, -- Chest\n    [229290] = true, -- Gloves\n    [229288] = true, -- Legs\n    \n    -- Shaman\n    [229262] = true, -- Helm\n    [229260] = true, -- Shoulder\n    [229265] = true, -- Chest\n    [229263] = true, -- Gloves\n    [229261] = true, -- Legs\n    \n    -- Warlock\n    [229325] = true, -- Helm\n    [229323] = true, -- Shoulder\n    [229328] = true, -- Chest\n    [229326] = true, -- Gloves\n    [229324] = true, -- Legs\n    \n    -- Warrior\n    [229235] = true, -- Helm\n    [229233] = true, -- Shoulder\n    [229238] = true, -- Chest\n    [229236] = true, -- Gloves\n    [229234] = true -- Legs\n}",
