["init"] = {
["custom"] = "aura_env.loaded = C_AddOns.IsAddOnLoaded(\"CauseseDB\")\nif aura_env.loaded then\n    --categoryNumber can be used to differentiate between casts in the conditions for coloring etc\n    \n    --[spellID] = {\"custom name\",category,\"show (true/false)\",\"soundFile\"},\n    aura_env.spellIDs = {\n        --spellIDs moved to CauseseDB\n        \n        --[432229] = {\"Knock\", 4, true, \"Knock.ogg\"}, --Example\n        \n    }\n    \n    -- this is only for spells where the mobs cast it for roleplay purposes and they should only show if target is in party\n    aura_env.rpspellIDs = {\n        [431637] = true, --Umbral Rush\n    }\n    \n    --[[\ndefault logic:\n- category 0 Tankbusters\n- category 1 Frontals\n- category 2 Pools\n- category 3 Special stuff\n- important Tankbusters\n]]\nend",
