},
["custom"] = "function(event, unit)\n    local errorMsg = \"|cff00bfff[WSD]|r |cffff2020Error!|r |cffffff00You did not set a spec for this dungeon.|r\"\n    \n    local inInstance, instanceType = IsInInstance()\n    if not inInstance or instanceType ~= \"raid\" then return false end\n    \n    if not UnitExists(unit) or not UnitIsEnemy(\"player\", unit) or not UnitCanAttack(\"player\", unit) then\n        return false\n    end\n    \n    local bossName = UnitName(unit)\n    local specID = GetSpecialization()\n    if not specID then return end\n    \n    local specIDNum = select(1, GetSpecializationInfo(specID))\n    if not specIDNum then return end\n    \n    local configID = C_ClassTalents.GetLastSelectedSavedConfigID(specIDNum)\n    if not configID then return end\n    \n    local configInfo = C_Traits.GetConfigInfo(configID)\n    if not configInfo or not configInfo.name then return end\n    \n    local playerSpecName = string.lower(configInfo.name)\n    local function isWrong(expectedName)\n        return expectedName and expectedName ~= \"\" and playerSpecName ~= string.lower(expectedName)\n    end\n    \n    local bossSpecMap = {\n        [\"The Geargrinder\"] = aura_env.config.wsd_lou.wsd_lou_1,\n        [\"Flarendo the Furious\"] = aura_env.config.wsd_lou.wsd_lou_2,\n        [\"Rik Reverb\"] = aura_env.config.wsd_lou.wsd_lou_3,\n        [\"Stix Bunkjunker\"] = aura_env.config.wsd_lou.wsd_lou_4,\n        [\"Sprocketmonger Lockenstock\"] = aura_env.config.wsd_lou.wsd_lou_5,\n        [\"One-Armed Bandit\"] = aura_env.config.wsd_lou.wsd_lou_6,\n        [\"Mug'Zee\"] = aura_env.config.wsd_lou.wsd_lou_7,\n        [\"Chrome King Gallywix\"] = aura_env.config.wsd_lou.wsd_lou_8,\n    }\n    \n    local expectedSpec = bossSpecMap[bossName]\n    if isWrong(expectedSpec) then\n        return true\n    end\n    \n    return false\nend",
