["Lunar Effect - MRT Helper Example"] = {
["outline"] = "OUTLINE",
["wagoID"] = "wxmTS5FG8",
["parent"] = "Lunar Effect - MRT Hook",
["displayText_format_p_time_dynamic_threshold"] = 60,
