["adjustedMax"] = "",
["adjustedMin"] = "",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["cooldownSwipe"] = true,
["cooldownEdge"] = false,
["icon"] = true,
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["debuffType"] = "HELPFUL",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["names"] = {
},
["spellIds"] = {
},
["custom"] = "--TSU\n--CLEU:SPELL_AURA_APPLIED, CLEU:SPELL_AURA_REMOVED, CLEU:SPELL_CAST_SUCCESS, CLEU:SPELL_EMPOWER_END, CLEU:SPELL_HEAL\nfunction(allStates, event, timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellId, ...)\n    if (event == \"OPTIONS\" or sourceGUID ~= UnitGUID(\"player\") or not subEvent) then\n        return false\n    end\n    \n    if (subEvent == \"SPELL_AURA_APPLIED\") then\n        -- Add stasis icons if not already created\n        if (spellId == aura_env.stasisId and not aura_env.active) then\n            aura_env.active = true\n            aura_env.spellIndex = 1\n            for i = 1, 3 do\n                allStates[i] = {\n                    show = true,\n                    changed = true,\n                    icon = 4630476,\n                    index = i\n                }\n            end\n            return true\n        end\n        \n        if (spellId == aura_env.stasisDoneId) then\n            return true\n        end\n    elseif (subEvent == \"SPELL_AURA_REMOVED\") then\n        if (spellId == aura_env.stasisDoneId) then\n            aura_env.active = false\n            for _,state in pairs(allStates) do\n                state.show = false\n                state.changed = true\n            end\n            return true\n        end\n    elseif (aura_env.active) then\n        local empowerLevel = nil\n        local addSpell = false\n        \n        if (subEvent == \"SPELL_CAST_SUCCESS\") then\n            local reactionMask = bit.band(destFlags, 0x000000F0)\n            local reactionFriendly = bit.band(destFlags, 0x00000010)\n            -- check if our spell is part of the list\n            -- note that this list does not include empowered spells\n            addSpell = aura_env.spellIds[spellId] == true and (reactionMask == 0 or reactionFriendly > 0)\n            \n            if (not addSpell and aura_env.isSpiritbloom(spellId)) then\n                addSpell = true\n                empowerLevel = aura_env.getMaxEmpowerLevel()\n            end\n        end\n        \n        if (subEvent == \"SPELL_EMPOWER_END\") then\n            if (aura_env.isDreamBreath(spellId) or aura_env.isSpiritbloom(spellId)) then\n                addSpell = true\n                empowerLevel = select(3, ...)\n            end\n        end\n        \n        if (subEvent == \"SPELL_HEAL\") then\n            -- Dream Breath does not trigger SPELL_CAST_SUCCESS for some reason\n            -- so we add Dream Breath from SPELL_HEAL\n            if (aura_env.isDreamBreath(spellId)) then\n                addSpell = true\n                empowerLevel = aura_env.getMaxEmpowerLevel()\n            end\n        end\n        \n        if (addSpell) then\n            return aura_env.addSpell(allStates, spellId, empowerLevel, timestamp)\n        end\n    end\nend",
["events"] = "CLEU:SPELL_AURA_APPLIED, CLEU:SPELL_AURA_REMOVED, CLEU:SPELL_CAST_SUCCESS, CLEU:SPELL_EMPOWER_END, CLEU:SPELL_HEAL",
["check"] = "event",
["unit"] = "player",
