["init"] = {
["custom"] = "aura_env.spellIds = {\n    [366155] = true, -- Reversion\n    [364343] = true, -- Echo\n    [360995] = true, -- Verdant Embrace\n    [355913] = true, -- Emerald Blossom\n    [360823] = true, -- Naturalize\n    [374251] = true, -- Cauterizing Flame\n    [373861] = true, -- Temporal Anomaly\n    [361469] = true, -- Living Flame\n    [431443] = true, -- Chrono Flames\n    [443328] = true, -- Engulf\n}\n\naura_env.isSpiritbloom = function (spellId)\n    return spellId == 367226 or spellId == 382731 or spellId == 367230\nend\n\naura_env.isDreamBreath = function (spellId)\n    return spellId == 355936 or spellId == 382614 or spellId == 355941\nend\n\naura_env.stasisId = 370537\naura_env.stasisDoneId = 370562\naura_env.spellIndex = 1\naura_env.lastEmpoweredSpellAddTime = 0\n\naura_env.addSpell = function(allStates, spellId, empowerLevel, timestamp)\n    -- block empowered spell if another empowered spell was recently added\n    if (aura_env.isSpiritbloom(spellId) or aura_env.isDreamBreath(spellId)) then\n        local timeDiff = timestamp - aura_env.lastEmpoweredSpellAddTime;\n        -- 0.1 = 100ms (I think?)\n        if timeDiff < 0.3 then\n            return\n        end\n        aura_env.lastEmpoweredSpellAddTime = timestamp\n    end\n    \n    local state = allStates[aura_env.spellIndex]\n    if (not state) then\n        return\n    end\n    local spellInfo = C_Spell.GetSpellInfo(spellId)\n    if (not spellInfo) then\n        return\n    end\n    state.icon = spellInfo.iconID\n    state.changed = true\n    state.spellId = spellId\n    state.empowerLevel = empowerLevel\n    \n    aura_env.spellIndex = aura_env.spellIndex + 1\n    return true\nend\n\naura_env.getMaxEmpowerLevel = function()\n    return IsPlayerSpell(375783) and 4 or 3\nend",
["do_custom"] = true,
},
},
